export const EVOLUTION_LEVELS = ["N1", "N2", "N3", "N4", "LI", "LF"];
export const SIMULADO_OPTIONS = ["N1", "N2", "N3", "N4", "LI", "LF", "NÃO AVALIADO"];

export interface SimuladoReadingDetails {
  modo?: "Não leu" | "Soletrou" | "Silabou" | "Leu" | string;
  palavras?: number;
  pseudopalavras?: number;
  texto?: number;
}

/**
 * MOTOR DE CLASSIFICAÇÃO OFICIAL DO PROGRAMA MUNICIPAL DE FLUÊNCIA LEITORA 2026
 *
 * 1. MATRIZ DE PONTUAÇÃO E CRITÉRIOS DE CORTE:
 * A. PRECEDÊNCIA QUALITATIVA (MODO DE LEITURA):
 *  - Se marcado como "Não leu" (ou valores zerados sem leitura) ➔ [NÍVEL 1]
 *  - Se marcado como "Soletrou" ➔ [NÍVEL 2]
 *  - Se marcado como "Silabou" ➔ [NÍVEL 3]
 *
 * B. PONTUAÇÃO QUANTITATIVA (QUANDO MARCADO COMO "LEU"):
 *  - LEITOR FLUENTE (LF): Exige cumulativamente:
 *      * Palavras: >= 50
 *      * Palavras Desconhecidas (Pseudopalavras): >= 30
 *      * Texto: >= 60
 *  - LEITOR INICIANTE (LI):
 *      * Palavras: entre 11 e 49
 *      * Palavras Desconhecidas: entre 11 e 29
 *      * Texto: entre 11 e 59
 *      (Ou estudantes com pontuação mista que não atingiram todos os 3 requisitos de Fluente).
 *  - NÍVEL 4 (PRÉ-LEITOR):
 *      * Palavras: até 10
 *      * Palavras Desconhecidas: até 10
 *      * Texto: até 10
 */
export function classifyReadingSimulado(details?: SimuladoReadingDetails): string {
  if (!details) return "NÃO AVALIADO";

  const modo = (details.modo || "").trim().toLowerCase();

  // A. PRECEDÊNCIA QUALITATIVA (MODO DE LEITURA)
  if (modo === "não leu" || modo === "nao leu" || modo === "não lido" || modo === "ausente") {
    return "N1";
  }
  if (modo === "soletrou" || modo === "soletração" || modo === "soletra") {
    return "N2";
  }
  if (modo === "silabou" || modo === "silabação" || modo === "silaba") {
    return "N3";
  }

  const palavras = details.palavras ?? 0;
  const pseudopalavras = details.pseudopalavras ?? 0;
  const texto = details.texto ?? 0;

  // Zerado e sem leitura expressa
  if (palavras === 0 && pseudopalavras === 0 && texto === 0 && (!modo || modo === "")) {
    return "N1";
  }

  // B. PONTUAÇÃO QUANTITATIVA (QUANDO MARCADO COMO "LEU" OU COM VALORES NUMÉRICOS)
  // LEITOR FLUENTE: Exige cumulativamente palavras >= 50, pseudopalavras >= 30, texto >= 60
  if (palavras >= 50 && pseudopalavras >= 30 && texto >= 60) {
    return "LF";
  }

  // NÍVEL 4 (PRÉ-LEITOR): palavras <= 10, pseudopalavras <= 10, texto <= 10
  if (palavras <= 10 && pseudopalavras <= 10 && texto <= 10) {
    return "N4";
  }

  // LEITOR INICIANTE: entre 11 e 49 / 11 e 29 / 11 e 59 ou pontuação mista
  return "LI";
}

/**
 * ESCALA ORDINAL OFICIAL 2026:
 * NÍVEL 1 (1) ➔ NÍVEL 2 (2) ➔ NÍVEL 3 (3) ➔ NÍVEL 4 (4) ➔ LEITOR INICIANTE (5) ➔ LEITOR FLUENTE (6)
 */
export const LEVEL_RANK: Record<string, number> = {
  "N1": 1, "Nível 1": 1, "NÍVEL 1": 1,
  "N2": 2, "Nível 2": 2, "NÍVEL 2": 2,
  "N3": 3, "Nível 3": 3, "NÍVEL 3": 3,
  "N4": 4, "Nível 4": 4, "NÍVEL 4": 4,
  "LI": 5, "Leitor Iniciante": 5, "LEITOR INICIANTE": 5,
  "LF": 6, "Leitor Fluente": 6, "LEITOR FLUENTE": 6
};

export interface EvolutionCalculationResult {
  delta: number | null;
  tier: "excepcional" | "expressivo" | "pontual" | "estavel" | "atencao" | "na";
  label: string;
  shortLabel: string;
  badgeBg: string;
  color: string;
  description: string;
}

export function calculateEvolutionDelta(entrada?: string, simulado?: string): EvolutionCalculationResult {
  if (!entrada || !simulado || entrada === "NÃO AVALIADO" || simulado === "NÃO AVALIADO" || entrada === "---" || simulado === "---") {
    return {
      delta: null,
      tier: "na",
      label: "---",
      shortLabel: "---",
      badgeBg: "bg-slate-100 text-slate-400 border border-slate-200",
      color: "bg-slate-100 text-slate-400 border border-slate-200 font-bold",
      description: "Sem dado em um dos polos"
    };
  }

  const rankEntrada = LEVEL_RANK[entrada];
  const rankSimulado = LEVEL_RANK[simulado];

  if (rankEntrada === undefined || rankSimulado === undefined) {
    return {
      delta: null,
      tier: "na",
      label: "---",
      shortLabel: "---",
      badgeBg: "bg-slate-100 text-slate-400 border border-slate-200",
      color: "bg-slate-100 text-slate-400 border border-slate-200 font-bold",
      description: "Sem dado válido"
    };
  }

  const delta = rankSimulado - rankEntrada;

  if (delta >= 3) {
    return {
      delta,
      tier: "excepcional",
      label: "AVANÇO EXCEPCIONAL",
      shortLabel: `EXCEPCIONAL (+${delta})`,
      badgeBg: "bg-blue-600 text-white",
      color: "bg-blue-600 text-white font-black shadow-xs",
      description: "Δ ≥ +3: Avanço de 3 ou mais níveis"
    };
  }
  if (delta === 2) {
    return {
      delta,
      tier: "expressivo",
      label: "AVANÇO EXPRESSIVO",
      shortLabel: "EXPRESSIVO (+2)",
      badgeBg: "bg-emerald-600 text-white",
      color: "bg-emerald-600 text-white font-black shadow-xs",
      description: "Δ = +2: Avanço de 2 níveis"
    };
  }
  if (delta === 1) {
    return {
      delta,
      tier: "pontual",
      label: "AVANÇO PONTUAL",
      shortLabel: "PONTUAL (+1)",
      badgeBg: "bg-amber-500 text-white",
      color: "bg-amber-500 text-white font-black shadow-xs",
      description: "Δ = +1: Avanço de 1 nível"
    };
  }
  if (delta === 0) {
    return {
      delta,
      tier: "estavel",
      label: "ESTÁVEL",
      shortLabel: "ESTÁVEL (0)",
      badgeBg: "bg-slate-500 text-white",
      color: "bg-slate-500 text-white font-bold",
      description: "Δ = 0: Manteve o mesmo nível"
    };
  }
  // delta < 0
  return {
    delta,
    tier: "atencao",
    label: "EM ATENÇÃO / REGRESSÃO",
    shortLabel: `EM ATENÇÃO (${delta})`,
    badgeBg: "bg-red-600 text-white",
    color: "bg-red-600 text-white font-bold shadow-xs",
    description: "Δ < 0: Regressão ou recuo de nível"
  };
}

